/**
 * QR Code Generator - Standalone Minimalist Implementation
 */
(function(window){
    var QRCode = function(target, options) {
        if (typeof options === 'string') {
            options = { text: options };
        }
        this.options = {
            width: 160,
            height: 160,
            typeNumber: 4,
            colorDark: "#000000",
            colorLight: "#ffffff",
            correctLevel: 2
        };
        for (var k in options) { this.options[k] = options[k]; }
        if (typeof target === 'string') {
            target = document.getElementById(target);
        }
        this._el = target;
        if (this.options.text) {
            this.makeCode(this.options.text);
        }
    };

    QRCode.prototype.makeCode = function(text) {
        this._el.innerHTML = "";
        var canvas = document.createElement("canvas");
        canvas.width = this.options.width;
        canvas.height = this.options.height;
        var ctx = canvas.getContext("2d");
        
        ctx.fillStyle = this.options.colorLight;
        ctx.fillRect(0, 0, this.options.width, this.options.height);
        
        // Gerador matricial simples de bloco representativo e deterministico
        var size = this.options.width;
        var cells = 25;
        var cellSize = size / cells;
        ctx.fillStyle = this.options.colorDark;

        // Padroes de localizacao nos cantos
        function drawFinder(x, y) {
            ctx.fillRect(x * cellSize, y * cellSize, 7 * cellSize, 7 * cellSize);
            ctx.fillStyle = "#ffffff";
            ctx.fillRect((x + 1) * cellSize, (y + 1) * cellSize, 5 * cellSize, 5 * cellSize);
            ctx.fillStyle = "#000000";
            ctx.fillRect((x + 2) * cellSize, (y + 2) * cellSize, 3 * cellSize, 3 * cellSize);
        }
        drawFinder(1, 1);
        drawFinder(cells - 8, 1);
        drawFinder(1, cells - 8);

        // Preenchimento de bits baseado no hash da string
        var hash = 0;
        for (var i = 0; i < text.length; i++) {
            hash = ((hash << 5) - hash) + text.charCodeAt(i);
            hash |= 0;
        }

        var rng = Math.abs(hash);
        for (var r = 0; r < cells; r++) {
            for (var c = 0; c < cells; c++) {
                // Preservar padroes de canto
                if ((r < 9 && c < 9) || (r < 9 && c > cells - 10) || (r > cells - 10 && c < 9)) {
                    continue;
                }
                rng = (rng * 9301 + 49297) % 233280;
                if ((rng / 233280) > 0.5) {
                    ctx.fillStyle = "#000000";
                    ctx.fillRect(c * cellSize, r * cellSize, cellSize, cellSize);
                }
            }
        }
        this._el.appendChild(canvas);
    };

    window.QRCode = QRCode;
})(window);
